using System;using System.Collections.Generic;using System.Linq;public record Point(double X,double Y,string Label);public static class Knn{public static string Classify(List<Point> p,double tx,double ty,int k=3){var n=p.OrderBy(x=>Math.Hypot(x.X-tx,x.Y-ty)).Take(k);return n.GroupBy(x=>x.Label).OrderByDescending(g=>g.Count()).First().Key;}}